19	// The tests of Deploy (DEVDESK-504, step 4). Deploy is called as
20	//
21	//	Deploy(ctx, runner, prober, clock, p, out) (DeployResult, error)
22	//
23	// against the scripted kubectl of preflight_test.go, wrapped by deployKubectl
24	// below (it adds the two writes of Deploy and the reads of the wait), a fake
25	// Prober and the fake clock of clock_test.go. No real kubectl, no network, no
26	// real wait.
27	//
28	// The kubectl calls the tests assume (arguments after "kubectl", without
29	// --context; "--request-timeout=<d>" may sit anywhere and is ignored):
30	//
31	//	RunPreflight(OpUp), first, whole (see preflight_test.go); nothing is written
32	//	                                 before it succeeds
33	//	apply --server-side --field-manager=devdesk-nexus-bench -f -
34	//	                                 stdin = RenderNamespace(p): the Namespace alone
35	//	apply --server-side --field-manager=devdesk-nexus-bench -f -
36	//	                                 stdin = Render(p): the whole stream, the
37	//	                                 Namespace again included (idempotent)
38	//	get pods -n <ns> -l app.kubernetes.io/name=nexus -o json    } once per round,
39	//	get pvc  -n <ns> -o json                                    } in either order
40	//
41	// The order of the arguments of the two reads is free ("-n", "-l" and "-o" may
42	// come in any order, "pvc" may be spelled "persistentvolumeclaims"); the
43	// resource, the namespace, the selector of the pods and "-o json" are not.
44	// Anything else fails the test as unscripted. A round is separated from the
45	// next by Clock.Sleep, and the cluster answers the n-th round with the n-th
46	// scripted state (the last one for ever after).
47	//
48	// Hypotheses about what Deploy does, to settle with the code:
49	//   - it checks ctx itself before the first write (the fake runner ignores ctx);
50	//   - each round reads the pods and the claims, diagnoses them, then asks the
51	//     Prober about every host; it returns after the first round in which at
52	//     least one host answered, with every host that answered in that round, in
53	//     the order of the hosts (p.Hosts, or 127.0.0.1 then the node InternalIP);
54	//   - a Prober base URL is "http://" + net.JoinHostPort(host, HTTPNodePort);
55	//   - the wait sleeps between 1 s and 10 s per round, and gives up at p.Timeout
56	//     (within one interval) with a Deadline BenchError naming the last state;
57	//   - ImagePull and Crash are returned at the first round that shows them; an
58	//     Unschedulable pod and a Pending claim are returned as PodPending no later
59	//     than the deadline, and a claim that is Pending in one round only (the
60	//     volume binds when the pod is scheduled) is not a failure;
61	//   - a warning is a line of out containing "warning" (case-insensitive) and
62	//     the host that did not answer; there is none when every host answered;
63	//   - no message and no line of out carries "password", the fake secret, or the
64	//     text of stderr (the Err of the BenchError keeps it for errors.Is).
65	
66	const (
67		deployPodName     = "nexus-7c9d8b6f4-x2k9p"
68		deployApplyLine   = "apply --server-side --field-manager=devdesk-nexus-bench -f -"
69		deployPodSelector = "app.kubernetes.io/name=nexus"
70		deployPVCName     = "nexus-data"
71	
72		// The wait polls between these two bounds (the plan says 5 s).
73		minPollInterval = time.Second
74		maxPollInterval = 10 * time.Second
75	)
76	
77	// ---- doubles ----------------------------------------------------------------
78	
79	// fakePod is the Nexus pod as one round sees it.
80	type fakePod struct {
81		name  string
82		phase string
83		// scheduled is the status of the PodScheduled condition: "" (no such
84		// condition yet), "True" or "False" (then the reason is Unschedulable).
85		scheduled     string
86		unschedulable string // message of the PodScheduled=False condition
87		ready         bool
88	
89		// The state of the container; none is reported for a pod that is not scheduled.
90		waiting, waitingMessage string // reason and message of state.waiting
91		running                 bool
92		lastTerminated          string // reason of lastState.terminated
93		restarts                int
94	}
95	
96	func (pd fakePod) object() map[string]any {
97		name := pd.name
98		if name == "" {
99			name = deployPodName
100		}
101		var conds []any
102		if pd.scheduled != "" {
103			c := map[string]any{"type": "PodScheduled", "status": pd.scheduled}
104			if pd.scheduled == "False" {
105				c["reason"] = "Unschedulable"
106				c["message"] = pd.unschedulable
107			}
108			conds = append(conds, c)
109		}
110		readyStatus := "False"
111		if pd.ready {
112			readyStatus = "True"
113		}
114		conds = append(conds, map[string]any{"type": "Ready", "status": readyStatus})
115		status := map[string]any{"phase": pd.phase, "conditions": conds}
116	
117		if pd.scheduled == "True" {
118			cs := map[string]any{"name": "nexus", "ready": pd.ready, "restartCount": pd.restarts, "image": "docker.io/sonatype/nexus3"}
119			switch {
120			case pd.waiting != "":
121				cs["state"] = map[string]any{"waiting": map[string]any{"reason": pd.waiting, "message": pd.waitingMessage}}
122			case pd.running:
123				cs["state"] = map[string]any{"running": map[string]any{"startedAt": "2026-11-16T12:00:05Z"}}
124			}
125			if pd.lastTerminated != "" {
126				cs["lastState"] = map[string]any{"terminated": map[string]any{"reason": pd.lastTerminated, "exitCode": 137}}
127			}
128			status["containerStatuses"] = []any{cs}
129		}
130		return map[string]any{
131			"metadata": map[string]any{"name": name, "labels": map[string]string{"app.kubernetes.io/name": "nexus"}},
132			"status":   status,
133		}
134	}
135	
136	func creatingPod() fakePod {
137		return fakePod{phase: "Pending", scheduled: "True", waiting: "ContainerCreating"}
138	}
139	func startingPod() fakePod { return fakePod{phase: "Running", scheduled: "True", running: true} }
140	func readyPod() fakePod {
141		return fakePod{phase: "Running", scheduled: "True", running: true, ready: true}
142	}
143	func unscheduledPod() fakePod { return fakePod{phase: "Pending"} }
144	func unschedulablePod(msg string) fakePod {
145		return fakePod{phase: "Pending", scheduled: "False", unschedulable: msg}
146	}
147	func pullFailedPod(reason string) fakePod {
148		return fakePod{
149			phase: "Pending", scheduled: "True", waiting: reason,
150			waitingMessage: `Failed to pull image "docker.io/sonatype/nexus3:3.98.1": rpc error: code = Unknown`,
151		}
152	}
153	
154	// clusterState is what the cluster answers in one round.
155	type clusterState struct {
156		pods     []fakePod
157		pvcPhase string // "" means the claim is not there
158	}
159	
160	func state(pvcPhase string, pods ...fakePod) clusterState {
161		return clusterState{pods: pods, pvcPhase: pvcPhase}
162	}
163	
164	// deployKubectl wraps the scripted kubectl with what Deploy writes and reads.
165	type deployKubectl struct {
166		*fakeKubectl
167		clk    *fakeClock
168		states []clusterState
169	
170		nsDoc, fullDoc []byte // what the two applies must send
171	
172		// failNamespace and failFull, when set, answer the apply of that stage
173		// with an error; the apply has then no effect on the cluster.
174		failNamespace, failFull *fakeReply
175	
176		lines    []string   // every call, normalized, in order
177		applies  []fakeCall // every apply, with its stdin
178		podReads int
179		pvcReads int
180	}
181	
182	var _ Runner = (*deployKubectl)(nil)
183	
184	func newDeployKubectl(t *testing.T, p Params, clk *fakeClock, states []clusterState) *deployKubectl {
185		t.Helper()
186		nsDoc, err := RenderNamespace(p)
187		if err != nil {
188			t.Fatalf("RenderNamespace: %v", err)
189		}
190		fullDoc, err := Render(p)
191		if err != nil {
192			t.Fatalf("Render: %v", err)
193		}
194		if len(states) == 0 {
195			states = []clusterState{state("Bound", readyPod())}
196		}
197		return &deployKubectl{fakeKubectl: newFakeKubectl(t, p), clk: clk, states: states, nsDoc: nsDoc, fullDoc: fullDoc}
198	}
199	
200	// current is the scripted state of the round being played: one round per sleep.
201	func (d *deployKubectl) current() clusterState {
202		return d.states[min(len(d.clk.sleeps), len(d.states)-1)]
203	}
204	
205	func (d *deployKubectl) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
206		norm := normalizeArgs(args)
207		joined := strings.Join(norm, " ")
208		d.lines = append(d.lines, joined)
209	
210		switch verb := verbOf(args); {
211		case verb == "apply":
212			return d.apply(joined, stdin)
213		case isWriteVerb(verb):
214			d.t.Errorf("unexpected write call %q: Deploy writes with apply only", args)
215			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
216		case verb == "get" && len(norm) > 1 && isPodResource(norm[1]):
217			d.podReads++
218			d.checkRead(norm, true)
219			return d.answerPods()
220		case verb == "get" && len(norm) > 1 && isPVCResource(norm[1]):
221			d.pvcReads++
222			d.checkRead(norm, false)
223			return d.answerPVCs()
224		}
225		return d.fakeKubectl.Run(ctx, stdin, args...)
226	}
227	
228	func isPodResource(r string) bool { return r == "pods" || r == "pod" }
229	func isPVCResource(r string) bool {
230		return r == "pvc" || r == "persistentvolumeclaims" || r == "persistentvolumeclaim"
231	}
232	
233	// checkRead verifies the namespace, the selector (pods) and the output of a read.
234	func (d *deployKubectl) checkRead(norm []string, withSelector bool) {
235		var ns, selector, output string
236		for i := 2; i < len(norm); i++ {
237			switch norm[i] {
238			case "-n", "--namespace":
239				i++
240				ns = at(norm, i)
241			case "-l", "--selector":
242				i++
243				selector = at(norm, i)
244			case "-o", "--output":
245				i++
246				output = at(norm, i)
247			default:
248				d.t.Errorf("unscripted argument %q in %q", norm[i], norm)
249			}
250		}
251		if ns != d.p.Namespace {
252			d.t.Errorf("%q reads namespace %q, the run is about %q", norm, ns, d.p.Namespace)
253		}
254		if output != "json" {
255			d.t.Errorf("%q must ask for -o json", norm)
256		}
257		if withSelector && selector != deployPodSelector {
258			d.t.Errorf("%q must select %s, got %q", norm, deployPodSelector, selector)
259		}
260	}
261	
262	func at(s []string, i int) string {
263		if i < len(s) {
264			return s[i]
265		}
266		return ""
267	}
268	
269	// apply records a write and, when it is accepted, applies its effect: the
270	// namespace exists (and is ours) after the first, the Service holds the
271	// NodePorts after the second.
272	func (d *deployKubectl) apply(joined string, stdin []byte) ([]byte, []byte, error) {
273		d.applies = append(d.applies, fakeCall{args: strings.Fields(joined), stdin: slices.Clone(stdin)})
274		if joined != deployApplyLine {
275			d.t.Errorf("apply call %q, want %q", joined, deployApplyLine)
276			return nil, []byte("the fake refuses this apply"), errFakeExit1
277		}
278		switch {
279		case bytes.Equal(stdin, d.nsDoc):
280			if d.failNamespace != nil {
281				return d.failNamespace.reply()
282			}
283			d.ours()
284			return []byte("namespace/" + d.p.Namespace + " serverside-applied\n"), nil, nil
285		case bytes.Equal(stdin, d.fullDoc):
286			if d.failFull != nil {
287				return d.failFull.reply()
288			}
289			d.ours().addService(d.p.Namespace, nexusServiceName, d.p.HTTPNodePort, d.p.DockerNodePort)
290			return []byte("service/nexus serverside-applied\n"), nil, nil
291		}
292		d.t.Errorf("apply sent a document that is neither RenderNamespace nor Render:\n%s", stdin)
293		return nil, []byte("the fake refuses this document"), errFakeExit1
294	}
295	
296	func (d *deployKubectl) answerPods() ([]byte, []byte, error) {
297		items := []any{}
298		for _, pd := range d.current().pods {
299			items = append(items, pd.object())
300		}
301		return d.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
302	}
303	
304	func (d *deployKubectl) answerPVCs() ([]byte, []byte, error) {
305		items := []any{}
306		if phase := d.current().pvcPhase; phase != "" {
307			items = append(items, map[string]any{
308				"metadata": map[string]any{"name": deployPVCName},
309				"spec": map[string]any{
310					"storageClassName": "local-path",
311					"resources":        map[string]any{"requests": map[string]any{"storage": d.p.StorageSize}},
312				},
313				"status": map[string]any{"phase": phase},
314			})
315		}
316		return d.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
317	}
318	
319	// fakeProber answers Ready by the host of the URL and the time of the fake
320	// clock: a host is ready from its entry of readyAfter on, and never when it has
321	// none. It is safe for concurrent use, because Deploy may probe the hosts in
322	// parallel.
323	type fakeProber struct {
324		clk        *fakeClock
325		readyAfter map[string]time.Duration
326	
327		mu   sync.Mutex
328		urls []string
329	}
330	
331	var _ Prober = (*fakeProber)(nil)
332	
333	func (f *fakeProber) Ready(ctx context.Context, baseURL string) error {
334		f.mu.Lock()
335		f.urls = append(f.urls, baseURL)
336		f.mu.Unlock()
337		if err := ctx.Err(); err != nil {
338			return err
339		}
340		u, err := url.Parse(baseURL)
341		if err != nil {
342			return fmt.Errorf("fake prober: bad URL %q: %w", baseURL, err)
343		}
344		if after, ok := f.readyAfter[u.Hostname()]; ok && f.clk.elapsed() >= after {
345			return nil
346		}
347		// The text carries a secret on purpose: it must not reach a message.
348		return fmt.Errorf("dial tcp %s: connect: connection refused (token=%s)", u.Host, fakeSecret)
349	}
350	
351	func (f *fakeProber) probed() []string {
352		f.mu.Lock()
353		defer f.mu.Unlock()
354		return slices.Clone(f.urls)
355	}
356	
357	// deployEnv is one Deploy run: its cluster, prober, clock and output.
358	type deployEnv struct {
359		t    *testing.T
360		p    Params
361		kube *deployKubectl
362		pr   *fakeProber
363		clk  *fakeClock
364		out  bytes.Buffer
365	}
366	
367	// deployParams are the defaults with a short deadline (the clock is fake, but a
368	// shorter one keeps the loops small).
369	func deployParams() Params {
370		p := Defaults()
371		p.Timeout = 2 * time.Minute
372		return p
373	}
374	
375	// newDeployEnv is a healthy cluster without the namespace. readyAfter says from
376	// when on each host answers (elapsed time of the fake clock).
377	func newDeployEnv(t *testing.T, p Params, readyAfter map[string]time.Duration, states ...clusterState) *deployEnv {
378		t.Helper()
379		clk := newFakeClock(t)
380		return &deployEnv{
381			t:    t,
382			p:    p,
383			kube: newDeployKubectl(t, p, clk, states),
384			pr:   &fakeProber{clk: clk, readyAfter: readyAfter},
385			clk:  clk,
386		}
387	}
388	
389	func (e *deployEnv) deploy(ctx context.Context) (DeployResult, error) {
390		e.t.Helper()
391		return Deploy(ctx, e.kube, e.pr, e.clk, e.p, &e.out)
392	}
393	
394	// warmUp is the usual way a bench starts: the pod is created, then starting,
395	// then ready, and the claim is bound from the first round on.
396	func warmUp() []clusterState {
397		return []clusterState{
398			state("Bound", creatingPod()),
399			state("Bound", startingPod()),
400			state("Bound", readyPod()),
401		}
402	}
403	
404	func hostAnswers(after time.Duration, hosts ...string) map[string]time.Duration {
405		m := map[string]time.Duration{}
406		for _, h := range hosts {
407			m[h] = after
408		}
409		return m
410	}
411	
412	// requireTwoApplies checks the writes of a run that got past the preflight:
413	// the Namespace alone, then the whole stream.
414	func (e *deployEnv) requireTwoApplies() {
415		e.t.Helper()
416		got := e.kube.applies
417		if len(got) != 2 {
418			e.t.Fatalf("%d apply calls, want 2 (the Namespace, then everything): %q", len(got), e.kube.lines)
419		}
420		if !bytes.Equal(got[0].stdin, e.kube.nsDoc) {
421			e.t.Errorf("the first apply did not send RenderNamespace(p):\n%s", got[0].stdin)
422		}
423		if !bytes.Equal(got[1].stdin, e.kube.fullDoc) {
424			e.t.Errorf("the second apply did not send Render(p):\n%s", got[1].stdin)
425		}
426	}
427	
428	// requireOrder checks that the preflight finished before the first write and
429	// that nothing was read from the pods before the second one.
430	func (e *deployEnv) requireOrder() {
431		e.t.Helper()
432		first := slices.Index(e.kube.lines, deployApplyLine)
433		second := -1
434		if first >= 0 {
435			second = first + 1 + slices.Index(e.kube.lines[first+1:], deployApplyLine)
436		}
437		if first < 0 || second <= first {
438			e.t.Fatalf("expected two apply calls in %q", e.kube.lines)
439		}
440		for _, want := range []string{"get services -A -o json", "get nodes -o json", "get namespace " + e.p.Namespace + " -o json"} {
441			if i := slices.Index(e.kube.lines, want); i < 0 || i > first {
442				e.t.Errorf("the preflight call %q is not before the first apply (index %d, apply at %d)", want, i, first)
443			}
444		}
445		for i, line := range e.kube.lines {
446			isRead := strings.HasPrefix(line, "get pods") || strings.HasPrefix(line, "get pvc") || strings.HasPrefix(line, "get persistentvolumeclaims")
447			if isRead && i < second {
448				e.t.Errorf("%q is called before the second apply (index %d, apply at %d)", line, i, second)
449			}
450		}
451	}
452	
453	// requirePollIntervals checks every wait is between the bounds.
454	func (e *deployEnv) requirePollIntervals() {
455		e.t.Helper()
456		for i, d := range e.clk.sleeps {
457			if d < minPollInterval || d > maxPollInterval {
458				e.t.Errorf("sleep #%d lasts %v, want between %v and %v", i+1, d, minPollInterval, maxPollInterval)
459			}
460		}
461	}
462	
463	// requireNoWrite checks nothing was written and nothing was waited for.
464	func (e *deployEnv) requireNoWrite() {
465		e.t.Helper()
466		if len(e.kube.applies) != 0 {
467			e.t.Errorf("Deploy wrote to the cluster: %q", e.kube.lines)
468		}
469		if e.kube.podReads != 0 || e.kube.pvcReads != 0 {
470			e.t.Errorf("Deploy read the pods (%d) or the claims (%d) although it stopped before the apply", e.kube.podReads, e.kube.pvcReads)
471		}
472		if got := e.pr.probed(); len(got) != 0 {
473			e.t.Errorf("Deploy probed %q although it stopped before the apply", got)
474		}
475	}
476	
477	// requireNoSecret checks that nothing Deploy said carries a password or a secret.
478	func (e *deployEnv) requireNoSecret(err error) {
479		e.t.Helper()
480		said := e.out.String()
481		if err != nil {
482			said += "\n" + err.Error()
483		}
484		for _, banned := range []string{"password", strings.ToLower(secretMarker), strings.ToLower(fakeSecret)} {
485			if strings.Contains(strings.ToLower(said), banned) {
486				e.t.Errorf("Deploy said %q, which contains %q", said, banned)
487			}
488		}
489	}
490	
491	// requireDeployKind checks err is a clean *BenchError of the kind.
492	func requireDeployKind(t *testing.T, err error, kind ErrKind) *BenchError {
493		t.Helper()
494		if err == nil {
495			t.Fatalf("Deploy succeeded, want a BenchError of kind %d", kind)
496		}
497		be := requireCleanError(t, err)
498		if be.Kind != kind {
499			t.Errorf("Kind = %d, want %d; message: %v", be.Kind, kind, err)
500		}
501		return be
502	}
503	
504	func requireMentions(t *testing.T, err error, mention, notMention []string) {
505		t.Helper()
506		msg := strings.ToLower(err.Error())
507		for _, want := range mention {
508			if !strings.Contains(msg, strings.ToLower(want)) {
509				t.Errorf("message %q does not mention %q", err.Error(), want)
510			}
511		}
512		for _, banned := range notMention {
513			if strings.Contains(msg, strings.ToLower(banned)) {
514				t.Errorf("message %q mentions %q, which is not the cause", err.Error(), banned)
515			}
516		}
517	}
