519	// ---- success ----------------------------------------------------------------
520	
521	func TestDeploySucceeds(t *testing.T) {
522		otherNS := func(p *Params) {
523			p.Namespace = "nexus-bench-2"
524			p.UpstreamURL = upstreamFor(p.Namespace)
525			p.HTTPNodePort, p.DockerNodePort = 30490, 30491
526		}
527		tests := []struct {
528			name       string
529			params     func(p *Params)
530			nodeAddrs  [][2]string // nil keeps the node of the fake cluster
531			readyAfter map[string]time.Duration
532			wantURLs   []string // every URL the prober may be asked about
533			want       DeployResult
534			warnAbout  string // a host the warning must name; "" means no warning
535		}{
536			{
537				name:       "both default hosts answer",
538				readyAfter: hostAnswers(15*time.Second, "127.0.0.1", fakeNodeIP),
539				wantURLs:   []string{"http://127.0.0.1:30481", "http://" + fakeNodeIP + ":30481"},
540				want:       DeployResult{ReachableHosts: []string{"127.0.0.1", fakeNodeIP}, NodeIP: fakeNodeIP},
541			},
542			{
543				name:       "only the loopback answers: success, with a warning about the node address",
544				readyAfter: hostAnswers(15*time.Second, "127.0.0.1"),
545				wantURLs:   []string{"http://127.0.0.1:30481", "http://" + fakeNodeIP + ":30481"},
