1033			ctx, cancel := context.WithCancel(context.Background())
1034			defer cancel()
1035			e.clk.onSleep = func(n int) {
1036				if n == 2 {
1037					cancel()
1038				}
1039			}
1040	
1041			_, err := e.deploy(ctx)
1042			if !errors.Is(err, context.Canceled) {
