1044			}
1045			var be *BenchError
1046			if errors.As(err, &be) && be.Kind == Deadline {
1047				t.Errorf("a cancellation is not a deadline: %v", err)
1048			}
1049			if got := len(e.clk.sleeps); got != 2 {
1050				t.Errorf("%d sleeps, want 2: it stops at the one that was cancelled", got)
1051			}
1052			e.requireTwoApplies()
1053			e.requireNoSecret(err)
1054		})
1055	}
