19	// The tests of Deploy (DEVDESK-504, step 4). Deploy is called as
20	//
21	//	Deploy(ctx, runner, prober, clock, p, out) (DeployResult, error)
22	//
23	// against the scripted kubectl of preflight_test.go, wrapped by deployKubectl
24	// below (it adds the two writes of Deploy and the reads of the wait), a fake
25	// Prober and the fake clock of clock_test.go. No real kubectl, no network, no
26	// real wait.
27	//
28	// The kubectl calls the tests assume (arguments after "kubectl", without
29	// --context; "--request-timeout=<d>" may sit anywhere and is ignored):
30	//
31	//	RunPreflight(OpUp), first, whole (see preflight_test.go); nothing is written
32	//	                                 before it succeeds
33	//	apply --server-side --field-manager=devdesk-nexus-bench -f -
34	//	                                 stdin = RenderNamespace(p): the Namespace alone
35	//	apply --server-side --field-manager=devdesk-nexus-bench -f -
36	//	                                 stdin = Render(p): the whole stream, the
37	//	                                 Namespace again included (idempotent)
38	//	get pods -n <ns> -l app.kubernetes.io/name=nexus -o json    } once per round,
39	//	get pvc  -n <ns> -o json                                    } in either order
40	//
41	// The order of the arguments of the two reads is free ("-n", "-l" and "-o" may
42	// come in any order, "pvc" may be spelled "persistentvolumeclaims"); the
43	// resource, the namespace, the selector of the pods and "-o json" are not.
44	// Anything else fails the test as unscripted. A round is separated from the
45	// next by Clock.Sleep, and the cluster answers the n-th round with the n-th
46	// scripted state (the last one for ever after).
47	//
48	// Hypotheses about what Deploy does, to settle with the code:
49	//   - it checks ctx itself before the first write (the fake runner ignores ctx);
50	//   - each round reads the pods and the claims, diagnoses them, then asks the
51	//     Prober about every host; it returns after the first round in which at
52	//     least one host answered, with every host that answered in that round, in
53	//     the order of the hosts (p.Hosts, or 127.0.0.1 then the node InternalIP);
54	//   - a Prober base URL is "http://" + net.JoinHostPort(host, HTTPNodePort);
55	//   - the wait sleeps between 1 s and 10 s per round, and gives up at p.Timeout
56	//     (within one interval) with a Deadline BenchError naming the last state;
57	//   - ImagePull and Crash are returned at the first round that shows them; an
58	//     Unschedulable pod and a Pending claim are returned as PodPending no later
59	//     than the deadline, and a claim that is Pending in one round only (the
60	//     volume binds when the pod is scheduled) is not a failure;
61	//   - a warning is a line of out containing "warning" (case-insensitive) and
62	//     the host that did not answer; there is none when every host answered;
63	//   - no message and no line of out carries "password", the fake secret, or the
64	//     text of stderr (the Err of the BenchError keeps it for errors.Is).
65	
66	const (
67		deployPodName     = "nexus-7c9d8b6f4-x2k9p"
68		deployApplyLine   = "apply --server-side --field-manager=devdesk-nexus-bench -f -"
69		deployPodSelector = "app.kubernetes.io/name=nexus"
70		deployPVCName     = "nexus-data"
71	
72		// The wait polls between these two bounds (the plan says 5 s).
73		minPollInterval = time.Second
74		maxPollInterval = 10 * time.Second
75	)
