164	// deployKubectl wraps the scripted kubectl with what Deploy writes and reads.
165	type deployKubectl struct {
166		*fakeKubectl
167		clk    *fakeClock
168		states []clusterState
169	
170		nsDoc, fullDoc []byte // what the two applies must send
171	
172		// failNamespace and failFull, when set, answer the apply of that stage
173		// with an error; the apply has then no effect on the cluster.
174		failNamespace, failFull *fakeReply
175	
176		lines    []string   // every call, normalized, in order
177		applies  []fakeCall // every apply, with its stdin
178		podReads int
