296	func (d *deployKubectl) answerPods() ([]byte, []byte, error) {
297		items := []any{}
298		for _, pd := range d.current().pods {
299			items = append(items, pd.object())
300		}
301		return d.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
302	}
