428	// requireOrder checks that the preflight finished before the first write and
429	// that nothing was read from the pods before the second one.
430	func (e *deployEnv) requireOrder() {
431		e.t.Helper()
432		first := slices.Index(e.kube.lines, deployApplyLine)
433		second := -1
434		if first >= 0 {
435			second = first + 1 + slices.Index(e.kube.lines[first+1:], deployApplyLine)
436		}
437		if first < 0 || second <= first {
438			e.t.Fatalf("expected two apply calls in %q", e.kube.lines)
439		}
440		for _, want := range []string{"get services -A -o json", "get nodes -o json", "get namespace " + e.p.Namespace + " -o json"} {
441			if i := slices.Index(e.kube.lines, want); i < 0 || i > first {
442				e.t.Errorf("the preflight call %q is not before the first apply (index %d, apply at %d)", want, i, first)
443			}
444		}
445		for i, line := range e.kube.lines {
446			isRead := strings.HasPrefix(line, "get pods") || strings.HasPrefix(line, "get pvc") || strings.HasPrefix(line, "get persistentvolumeclaims")
447			if isRead && i < second {
448				e.t.Errorf("%q is called before the second apply (index %d, apply at %d)", line, i, second)
449			}
450		}
451	}
