453	// requirePollIntervals checks every wait is between the bounds.
454	func (e *deployEnv) requirePollIntervals() {
455		e.t.Helper()
456		for i, d := range e.clk.sleeps {
457			if d < minPollInterval || d > maxPollInterval {
458				e.t.Errorf("sleep #%d lasts %v, want between %v and %v", i+1, d, minPollInterval, maxPollInterval)
459			}
460		}
461	}
