1019	
1020			_, err := e.deploy(ctx)
1021			if !errors.Is(err, context.Canceled) {
1022				t.Fatalf("Deploy with a cancelled context = %v, want context.Canceled", err)
1023			}
1024			if len(e.kube.applies) != 0 {
1025				t.Errorf("Deploy wrote after the context was cancelled: %q", e.kube.lines)
1026			}
