2	
3	import (
4		"context"
5		"errors"
6		"net/http"
7		"net/http/httptest"
8		"strings"
9		"sync/atomic"
10		"testing"
11		"time"
12	)
13	
14	// The tests of the real Prober (DEVDESK-504, step 4, probe.go), against
15	// httptest servers on the loopback: no cluster, no external network.
16	//
17	// Hypotheses to settle with the code:
18	//   - the constructor is NewProber() Prober;
19	//   - Ready sends one unauthenticated GET to <baseURL>/service/rest/v1/status
20	//     and returns nil on a 200 and only then;
21	//   - a redirect is never followed (an error, the target is never reached);
22	//   - the error says the status code or the failure, never the body.
23	
24	const probeStatusPath = "/service/rest/v1/status"
25	
26	func TestProberReady(t *testing.T) {
27		tests := []struct {
28			name       string
29			status     int
30			body       string
31			location   string // Location header, when set
32			wantErr    bool
33			wantStatus string // text the error must carry
34		}{
35			{name: "200 means ready", status: http.StatusOK, body: "{}"},
36			{name: "503 while Nexus starts", status: http.StatusServiceUnavailable, body: "starting", wantErr: true, wantStatus: "503"},
37			{name: "404 on a wrong port", status: http.StatusNotFound, wantErr: true, wantStatus: "404"},
38			{name: "401 is not ready", status: http.StatusUnauthorized, wantErr: true, wantStatus: "401"},
39			{name: "204 is not a 200", status: http.StatusNoContent, wantErr: true, wantStatus: "204"},
40			{name: "the body of a failure stays out of the error", status: http.StatusInternalServerError, body: "boom " + fakeSecret, wantErr: true, wantStatus: "500"},
41		}
42		for _, tt := range tests {
43			t.Run(tt.name, func(t *testing.T) {
44				var method, path, auth atomic.Value
45				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
46					method.Store(r.Method)
47					path.Store(r.URL.Path)
48					auth.Store(r.Header.Get("Authorization"))
49					w.WriteHeader(tt.status)
50					_, _ = w.Write([]byte(tt.body))
51				}))
52				defer srv.Close()
53	
54				err := NewProber().Ready(context.Background(), srv.URL)
55				if tt.wantErr != (err != nil) {
56					t.Fatalf("Ready = %v, want error: %v", err, tt.wantErr)
57				}
58				if got := method.Load(); got != http.MethodGet {
59					t.Errorf("method = %v, want GET", got)
60				}
61				if got := path.Load(); got != probeStatusPath {
62					t.Errorf("path = %v, want %s", got, probeStatusPath)
63				}
64				if got := auth.Load(); got != "" {
65					t.Errorf("the probe sent credentials: %v", got)
66				}
67				if err != nil {
68					if !strings.Contains(err.Error(), tt.wantStatus) {
69						t.Errorf("error %q does not carry the status %s", err, tt.wantStatus)
70					}
71					if strings.Contains(err.Error(), fakeSecret) {
72						t.Errorf("error %q carries the body of the response", err)
73					}
74				}
75			})
76		}
77	}
78	
79	func TestProberDoesNotFollowRedirects(t *testing.T) {
80		var reached atomic.Int32
81		target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
82			reached.Add(1)
83			w.WriteHeader(http.StatusOK)
84		}))
85		defer target.Close()
86		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
87			http.Redirect(w, r, target.URL+probeStatusPath, http.StatusFound)
88		}))
89		defer srv.Close()
90	
91		if err := NewProber().Ready(context.Background(), srv.URL); err == nil {
92			t.Error("Ready followed a redirect to another origin and reported ready")
93		}
94		if reached.Load() != 0 {
95			t.Error("the redirect target was contacted")
96		}
97	}
98	
99	func TestProberFailsWhenNothingListens(t *testing.T) {
100		srv := httptest.NewServer(http.NotFoundHandler())
101		url := srv.URL
102		srv.Close()
103	
104		if err := NewProber().Ready(context.Background(), url); err == nil {
105			t.Error("Ready succeeded against a closed server")
106		}
107	}
108	
109	func TestProberHonoursTheContext(t *testing.T) {
110		t.Run("already cancelled", func(t *testing.T) {
111			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) }))
112			defer srv.Close()
113			ctx, cancel := context.WithCancel(context.Background())
114			cancel()
115			if err := NewProber().Ready(ctx, srv.URL); !errors.Is(err, context.Canceled) {
116				t.Errorf("Ready with a cancelled context = %v, want context.Canceled", err)
117			}
118		})
119	
120		t.Run("a server that never answers is cut by the deadline of the context", func(t *testing.T) {
121			srv := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) { <-r.Context().Done() }))
122			defer srv.Close()
123			ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
124			defer cancel()
125			if err := NewProber().Ready(ctx, srv.URL); !errors.Is(err, context.DeadlineExceeded) {
126				t.Errorf("Ready on a silent server = %v, want context.DeadlineExceeded", err)
127			}
128		})
129	}
